CAT = "dethGefahren"; SEG = "GEF"
# Gefahrenlehre. (Frage, richtige Antwort, [3 falsche], Erläuterung). Richtige Antwort zuerst.
Q = [
("Sie fahren innerorts an parkenden Autos vorbei. Zwischen zwei Autos rollt ein Ball auf die Fahrbahn. Womit müssen Sie rechnen?",
 "Dass ein Kind hinterherläuft", ["Dass der Ball liegen bleibt", "Dass ein Hund ihn zurückholt", "Dass der Ball am Bordstein abprallt"],
 "Kinder achten beim Spielen kaum auf den Verkehr und laufen einem Ball oft ohne zu schauen nach. Bremsbereit sein und langsamer fahren."),
("Ein Schulbus steht mit eingeschaltetem Warnblinklicht an einer Haltestelle. Wie dürfen Sie an ihm vorbeifahren?",
 "Nur mit Schrittgeschwindigkeit", ["Mit höchstens 30 km/h", "Mit gleicher Geschwindigkeit, aber hupend", "Zügig, um die Haltestelle frei zu machen"],
 "Nach § 20 Abs. 4 StVO darf an einem haltenden Bus mit Warnblinklicht nur mit Schrittgeschwindigkeit und mit ausreichendem Abstand vorbeigefahren werden. Das gilt auch für den Gegenverkehr."),
("Ein Linienbus nähert sich mit eingeschaltetem Warnblinklicht einer Haltestelle. Was gilt für Sie?",
 "Sie dürfen ihn nicht überholen", ["Sie dürfen ihn nur links überholen", "Sie müssen sofort hinter ihm halten", "Sie dürfen ihn rechts überholen"],
 "§ 20 Abs. 3 StVO: Busse, die sich mit Warnblinklicht einer Haltestelle nähern, dürfen nicht überholt werden."),
("Eine ältere Frau mit Gehstock ist erst in der Mitte der Fahrbahn, als Ihre Ampel auf Grün springt. Was tun Sie?",
 "Warten, bis sie drüben ist", ["Anfahren, weil Ihre Ampel Grün zeigt", "Hupen, damit sie schneller geht", "Langsam um sie herumfahren"],
 "Grün erlaubt das Fahren nur, wenn niemand gefährdet wird. Ältere Menschen brauchen mehr Zeit; lassen Sie sie in Ruhe die Straße verlassen."),
("Am Fahrbahnrand stehen Kinder, die unsicher wirken. Wie müssen Sie sich nach der StVO verhalten?",
 "Langsamer fahren und bremsbereit sein", ["Hupen, damit sie stehen bleiben", "Schneller fahren, um rasch vorbei zu sein", "Kurz die Lichthupe betätigen"],
 "§ 3 Abs. 2a StVO verlangt gegenüber Kindern, hilfsbedürftigen und älteren Menschen, die Geschwindigkeit zu verringern und bremsbereit zu sein, damit niemand gefährdet wird."),
("Bei starkem Regen beginnt Ihr Auto auf der Autobahn aufzuschwimmen (Aquaplaning). Was ist richtig?",
 "Auskuppeln und nicht bremsen", ["Kräftig bremsen und gegenlenken", "Kräftig Gas geben", "Das Lenkrad schnell hin und her drehen"],
 "Beim Aufschwimmen haben die Reifen keinen Kontakt zur Straße. Kupplung treten, nicht bremsen und geradeaus lenken, bis die Reifen wieder greifen."),
("Wodurch steigt die Gefahr von Aquaplaning am stärksten?",
 "Hohes Tempo und abgefahrene Reifen", ["Eingeschaltetes Abblendlicht", "Ein leerer Kofferraum", "Neue Reifen mit tiefem Profil"],
 "Je schneller Sie fahren und je weniger Profil die Reifen haben, desto weniger Wasser wird verdrängt. Dann schwimmt das Fahrzeug leichter auf."),
("Die Temperatur liegt knapp über 0 °C. Sie fahren auf eine Brücke zu. Womit müssen Sie dort besonders rechnen?",
 "Mit Glätte auf der Brücke", ["Mit besserer Bodenhaftung", "Mit einer niedrigeren Höchstgeschwindigkeit", "Mit Fußgängern auf der Fahrbahn"],
 "Brücken kühlen von oben und unten aus. Dort kann die Fahrbahn schon vereist sein, während sie davor und dahinter noch trocken ist."),
("Wegen Nebels beträgt die Sichtweite weniger als 50 m. Wie schnell dürfen Sie höchstens fahren?",
 "50 km/h", ["20 km/h", "30 km/h", "40 km/h"],
 "§ 3 Abs. 1 StVO: Bei Sichtweite unter 50 m durch Nebel, Schneefall oder Regen darf nicht schneller als 50 km/h gefahren werden, wenn nötig langsamer."),
("Wann dürfen Sie die Nebelschlussleuchte einschalten?",
 "Bei Nebel mit Sicht unter 50 m", ["Bei Regen in der Nacht", "Bei Regen mit Sicht unter 150 m", "Wenn jemand zu dicht auffährt"],
 "§ 17 Abs. 3 StVO erlaubt die Nebelschlussleuchte nur, wenn die Sichtweite durch Nebel weniger als 50 m beträgt. Sonst blendet sie die Nachfolgenden."),
("Nachts steht ein Reh im Scheinwerferlicht auf der Fahrbahn. Wie reagieren Sie richtig?",
 "Abblenden, bremsen und hupen", ["Fernlicht anlassen und ausweichen", "Gas geben, damit es flüchtet", "Scharf in den Gegenverkehr ausweichen"],
 "Fernlicht blendet das Tier, es bleibt dann stehen. Abblenden, kontrolliert bremsen und hupen gibt ihm die Chance, wegzulaufen."),
("Ein Zusammenstoß mit einem Wildschwein lässt sich nicht mehr vermeiden. Wie verhalten Sie sich?",
 "Spur halten und kräftig bremsen", ["Ruckartig nach rechts ausweichen", "Die Bremse lösen und ausrollen", "Auf die Gegenfahrbahn ausweichen"],
 "Ein unkontrolliertes Ausweichmanöver endet oft am Baum oder im Gegenverkehr. Der Aufprall auf das Tier ist meist weniger gefährlich."),
("Im Herbst liegt nasses Laub auf der Straße. Worauf müssen Sie sich einstellen?",
 "Auf einen längeren Bremsweg", ["Auf bessere Haftung der Reifen", "Auf eine Pflicht zum Fernlicht", "Auf ein Tempolimit von 30 km/h"],
 "Nasses Laub wirkt wie ein Schmierfilm. Die Reifen haften schlechter, der Bremsweg wird länger, also langsamer fahren und mehr Abstand halten."),
("Sie werden nachts vom Gegenverkehr geblendet. Wie reagieren Sie?",
 "Langsamer fahren und rechts orientieren", ["Selbst kurz das Fernlicht einschalten", "Direkt in die Scheinwerfer blicken", "Schneller fahren, um vorbeizukommen"],
 "Wer geblendet ist, sieht für einige Sekunden fast nichts. Tempo verringern und sich am rechten Fahrbahnrand orientieren."),
("Warum müssen Sie in der Dämmerung besonders auf Radfahrer achten?",
 "Sie werden leicht übersehen", ["Sie haben dann immer Vorfahrt", "Sie dürfen dann ohne Licht fahren", "Sie fahren dann immer schneller"],
 "In der Dämmerung lässt das Sehvermögen nach und Kontraste verschwinden. Radfahrer sind schmal und werden oft erst spät erkannt."),
("Sie fahren auf der Autobahn neben einem Lkw im rechten Fahrstreifen. Was ist richtig?",
 "Nicht länger als nötig neben ihm fahren", ["Möglichst lange neben ihm bleiben", "Durch Hupen auf sich aufmerksam machen", "Dicht hinter ihm im Windschatten fahren"],
 "Neben dem Lkw sind Sie leicht im toten Winkel. Überholen Sie zügig oder bleiben Sie mit Abstand dahinter."),
("Sie fahren auf einer Landstraße 90 km/h. Welcher Abstand passt nach der Faustregel „halber Tacho“?",
 "45 m", ["15 m", "25 m", "30 m"],
 "Halber Tacho: die Hälfte der Geschwindigkeitszahl in Metern. Bei 90 km/h also 45 m."),
("Wie lang ist bei 70 km/h der Reaktionsweg nach der Faustformel (Geschwindigkeit : 10) × 3?",
 "21 m", ["28 m", "35 m", "49 m"],
 "70 : 10 = 7, mal 3 ergibt 21 m. So weit fahren Sie, bevor Sie überhaupt anfangen zu bremsen."),
("Wie lang ist bei 80 km/h der normale Bremsweg nach der Faustformel (Geschwindigkeit : 10) × (Geschwindigkeit : 10)?",
 "64 m", ["16 m", "24 m", "48 m"],
 "80 : 10 = 8, und 8 × 8 = 64 m. Bei einer Gefahrenbremsung wäre es etwa die Hälfte."),
("Wie lang ist bei 100 km/h der Bremsweg einer Gefahrenbremsung nach der Faustformel?",
 "50 m", ["75 m", "100 m", "200 m"],
 "Normaler Bremsweg: 10 × 10 = 100 m. Bei einer Gefahrenbremsung wird er halbiert, also 50 m."),
("Wie lang ist nach den Faustformeln der Anhalteweg bei 50 km/h (Reaktionsweg plus normaler Bremsweg)?",
 "40 m", ["15 m", "25 m", "30 m"],
 "Reaktionsweg 5 × 3 = 15 m, Bremsweg 5 × 5 = 25 m. Zusammen ergibt das 40 m."),
("Sie verdoppeln Ihre Geschwindigkeit. Wie verändert sich der Bremsweg?",
 "Er wird etwa viermal so lang", ["Er wird etwa doppelt so lang", "Er bleibt etwa gleich lang", "Er wird etwa dreimal so lang"],
 "Der Bremsweg wächst mit dem Quadrat der Geschwindigkeit. Doppeltes Tempo bedeutet etwa vierfachen Bremsweg."),
("Welche Strecke legen Sie bei 72 km/h in einer Sekunde zurück?",
 "20 m", ["7,2 m", "36 m", "72 m"],
 "72 km/h geteilt durch 3,6 ergibt 20 Meter pro Sekunde. Schon eine Sekunde Ablenkung bedeutet 20 m Blindflug."),
("Eine Kurve ist schwer einsehbar. Wie fahren Sie richtig hinein?",
 "Vor der Kurve langsamer werden", ["In der Kurve kräftig bremsen", "Die Kurve innen schneiden", "Mit gleichem Tempo hineinfahren"],
 "Bremsen Sie vor der Kurve auf ein passendes Tempo herunter. Starkes Bremsen in der Kurve kann das Fahrzeug ausbrechen lassen."),
("Warum werden Motorradfahrer an Kreuzungen oft übersehen?",
 "Wegen ihrer schmalen Silhouette", ["Weil sie kein Abblendlicht haben", "Weil sie nur auf Radwegen fahren", "Weil sie keine Blinker brauchen"],
 "Ein Motorrad ist schmal, seine Geschwindigkeit wird leicht unterschätzt. Schauen Sie vor dem Abbiegen bewusst zweimal hin."),
("Sie haben am Straßenrand geparkt und wollen auf der Fahrerseite aussteigen. Wie vermeiden Sie einen Unfall mit Radfahrern?",
 "Die Tür mit der rechten Hand öffnen", ["Die Tür schnell ganz aufstoßen", "Vor dem Aussteigen kurz hupen", "Nur auf Fußgänger achten"],
 "Mit der rechten Hand drehen Sie den Oberkörper und sehen nach hinten (holländischer Griff). § 14 Abs. 1 StVO: Beim Aussteigen darf niemand gefährdet werden."),
("Ein Linienbus hält auf der gegenüberliegenden Seite an einer Haltestelle. Womit rechnen Sie?",
 "Mit Fahrgästen, die vor dem Bus queren", ["Mit einem Bus, der gleich wendet", "Mit Glätte an der Haltestelle", "Mit einem Lkw hinter dem Bus"],
 "Aussteigende Fahrgäste laufen oft vor oder hinter dem Bus über die Straße, ohne auf den Verkehr zu achten."),
("Auf der Autobahn sehen Sie hinter einer Kuppe Warnblinklichter. Was tun Sie?",
 "Tempo verringern und mit Stau rechnen", ["Auf den linken Fahrstreifen wechseln", "Fernlicht einschalten und weiterfahren", "Auf dem Seitenstreifen vorbeifahren"],
 "Warnblinklicht hinter einer Kuppe warnt meist vor einem Stauende. Früh abbremsen und genug Abstand halten."),
("Sie nähern sich auf der Autobahn rasch einem Stauende. Wie warnen Sie den nachfolgenden Verkehr?",
 "Mit dem Warnblinklicht", ["Mit der Nebelschlussleuchte", "Mit der Lichthupe nach hinten", "Mit dem rechten Blinker"],
 "§ 16 Abs. 2 StVO erlaubt das Warnblinklicht, wenn Sie sich einem Stau nähern. So erkennen die Nachfolgenden die Gefahr früher."),
("An einer Waldschneise auf der Landstraße weht plötzlich starker Seitenwind. Was tun Sie?",
 "Langsamer fahren und gegenlenken", ["Schneller fahren für mehr Stabilität", "Das Lenkrad kurz loslassen", "Auf die Gegenfahrbahn ausweichen"],
 "Seitenwind kann das Auto versetzen. Mit weniger Tempo und festem Griff am Lenkrad bleiben Sie in der Spur."),
("Sie fahren am Tag in einen langen Tunnel ein. Was ist richtig?",
 "Abblendlicht einschalten", ["Sonnenbrille aufsetzen", "Nebelscheinwerfer einschalten", "Nur mit Standlicht fahren"],
 "Wer durch einen Tunnel (Zeichen 327) fährt, muss Abblendlicht einschalten. Eine Sonnenbrille sollten Sie vorher abnehmen, weil die Augen sich an Dunkelheit gewöhnen müssen."),
("Ein Fußgänger mit weißem Langstock steht am Fahrbahnrand. Was zeigt der Stock an?",
 "Die Person ist blind", ["Die Person ist ein Schülerlotse", "Die Person arbeitet an der Straße", "Die Person regelt den Verkehr"],
 "Ein weißer Stock kennzeichnet blinde oder stark sehbehinderte Menschen. Sie müssen besonders rücksichtsvoll und bremsbereit sein."),
("Ein etwa sechsjähriges Kind fährt vor Ihnen mit dem Rad auf dem Gehweg. Womit müssen Sie rechnen?",
 "Dass es plötzlich auf die Fahrbahn fährt", ["Dass es immer Handzeichen gibt", "Dass es sicher geradeaus weiterfährt", "Dass es die Vorfahrtregeln kennt"],
 "Kinder bis 8 Jahre müssen mit dem Rad den Gehweg benutzen (§ 2 Abs. 5 StVO). Sie können Gefahren und Geschwindigkeiten noch nicht sicher einschätzen. Rechnen Sie mit plötzlichen Richtungswechseln."),
("Morgens bei Plusgraden fahren Sie durch ein Waldstück. Wo ist am ehesten noch Glätte zu erwarten?",
 "An schattigen Stellen", ["Auf sonnigen Geraden", "Auf frisch gestreuten Abschnitten", "Auf Asphalt nahe Häusern"],
 "Wo die Sonne nicht hinkommt, taut Eis viel später. Rechnen Sie in Waldstücken und an Hängen mit überfrierender Nässe."),
("Nach langer Trockenheit beginnt es zu regnen. Warum ist die Fahrbahn jetzt besonders rutschig?",
 "Wasser mischt sich mit Staub und Gummiabrieb", ["Der Asphalt wird durch den Regen weich und klebrig", "Die Reifen kühlen dabei stark ab", "Das Profil füllt sich mit Sand"],
 "Die ersten Regentropfen bilden mit Staub, Öl und Gummiabrieb einen schmierigen Film. Erst starker Regen spült ihn weg."),
("Nachts erkennen Sie dunkel gekleidete Fußgänger im Abblendlicht erst spät. Wie stellen Sie sich darauf ein?",
 "Langsamer fahren als am Tag", ["Dauerhaft die Nebelscheinwerfer nutzen", "Öfter die Lichthupe geben", "Weiter zur Fahrbahnmitte fahren"],
 "Abblendlicht reicht nicht weit. Passen Sie die Geschwindigkeit so an, dass Sie innerhalb der beleuchteten Strecke anhalten können."),
("Was bedeutet „Fahren auf Sicht“?",
 "Innerhalb der Sichtweite anhalten können", ["Nur bei Sonnenschein fahren", "Immer der Markierung folgen", "So schnell fahren, wie der Vordermann es vormacht"],
 "§ 3 Abs. 1 StVO: Sie dürfen nur so schnell fahren, dass Sie innerhalb der überschaubaren Strecke halten können."),
("Warum ist Überholen auf Landstraßen besonders gefährlich?",
 "Der Gegenverkehr ist schwer einzuschätzen", ["Dort gilt immer ein Überholverbot", "Dort fahren keine Lkw", "Landstraßen haben keine Leitlinien"],
 "Geschwindigkeit und Entfernung entgegenkommender Fahrzeuge werden leicht unterschätzt. Überholen Sie nur mit sehr viel Sicht."),
("Die tief stehende Sonne blendet Sie. Was tun Sie?",
 "Langsamer fahren und die Sonnenblende nutzen", ["Schneller fahren, um aus der Sonne zu kommen", "Die Augen kurz schließen", "Dicht auffahren, um im Schatten zu sein"],
 "Wer geblendet wird, sieht Hindernisse zu spät. Tempo anpassen, Blende herunterklappen und saubere Scheiben helfen."),
("Auf einer schmalen Landstraße kommt Ihnen ein breiter Traktor entgegen. Was tun Sie?",
 "Weit rechts fahren und notfalls anhalten", ["In der Mitte bleiben, er muss ausweichen", "Mit Lichthupe Vorrang verlangen", "Zügig beschleunigen und vorbei"],
 "An Engstellen gilt gegenseitige Rücksicht. Wer nicht sicher aneinander vorbeikommt, hält an und lässt durch."),
("Morgens gegen 7.30 Uhr fahren Sie an einer Grundschule vorbei. Womit müssen Sie rechnen?",
 "Mit vielen Kindern auf dem Schulweg", ["Mit gesperrten Gehwegen", "Mit leeren Straßen vor Schulbeginn", "Mit weniger Fußgängern als sonst"],
 "Vor Schulbeginn sind viele Kinder unterwegs, oft in Gruppen und abgelenkt. Fahren Sie besonders vorsichtig."),
("Bei starkem Schneefall ist die Sicht am Tag erheblich behindert. Welche Beleuchtung ist vorgeschrieben?",
 "Abblendlicht", ["Nur Standlicht", "Dauerhaft Fernlicht", "Nur die Nebelschlussleuchte"],
 "§ 17 Abs. 3 StVO: Bei erheblicher Sichtbehinderung durch Nebel, Schneefall oder Regen muss auch am Tag mit Abblendlicht gefahren werden."),
("Vor Ihnen fährt ein Traktor, der vom Acker kommt und Erde verliert. Was müssen Sie erwarten?",
 "Eine rutschige Fahrbahn", ["Eine bessere Haftung", "Ein Überholverbot", "Eine Umleitung"],
 "Erde und Schlamm auf der Straße wirken bei Nässe wie Schmierseife. Bremsweg und Rutschgefahr nehmen zu."),
("Sie fahren auf nasser Fahrbahn durch eine Kurve. Wodurch bricht das Auto am ehesten aus?",
 "Durch starkes Bremsen in der Kurve", ["Durch gleichmäßiges Tempo", "Durch eingeschaltetes Abblendlicht", "Durch Bremsen vor der Kurve"],
 "In der Kurve wird die Haftung schon für die Seitenführung gebraucht. Zusätzliches starkes Bremsen kann sie überfordern."),
("Ein Ball rollt auf die Fahrbahn, Sie können noch gefahrlos anhalten. Wie lange bleiben Sie aufmerksam?",
 "Bis klar ist, dass kein Kind folgt", ["Bis der Ball am Rand liegt", "Nur so lange, wie Sie noch bremsen müssen", "Bis hinter Ihnen jemand hupt"],
 "Ein Kind kann auch Sekunden später zwischen den Autos hervorkommen. Fahren Sie erst langsam weiter, wenn die Lage klar ist."),
("Auf der Gegenfahrbahn hat sich ein langer Stau gebildet. Womit müssen Sie an Lücken im Stau rechnen?",
 "Mit Fußgängern, die aus der Lücke kommen", ["Mit Fahrzeugen, die rückwärts fahren", "Mit Bauarbeiten am Straßenrand", "Mit plötzlichem Grün an der nächsten Ampel"],
 "Wartende lassen oft Lücken für Querverkehr frei. Aus ihnen können Fußgänger oder Linksabbieger hervorkommen, die Sie spät sehen."),
("Was erhöht die Unfallgefahr bei einer Fahrt in der Nacht am stärksten?",
 "Eingeschränkte Sicht und Müdigkeit", ["Weniger Verkehr auf den Straßen", "Kühlere Luft im Motorraum", "Hellere Straßenlaternen"],
 "Nachts sehen Sie weniger, Entfernungen sind schwerer zu schätzen und viele Menschen sind müde. Fahren Sie langsamer und machen Sie Pausen."),
("Eine Ampel an einer Baustelle regelt einspurigen Wechselverkehr. Wo halten Sie bei Rot?",
 "Vor der Ampel an der Haltlinie", ["Direkt neben der Baustelle", "Hinter dem ersten Gegenfahrzeug", "Am Ende der Baustelle"],
 "Bei Rot halten Sie vor der Ampel. Erst bei Grün fahren Sie in den einspurigen Bereich, denn sonst stoßen Sie dort auf den Gegenverkehr."),
("Sie fahren an einem sonnigen Tag durch eine Allee mit ständigem Wechsel von Licht und Schatten. Was ist die besondere Gefahr?",
 "Andere werden im Schatten spät erkannt", ["Die Bäume verdecken die Ampeln", "Die Reifen werden dort heißer", "Der Tacho zeigt dort falsch an"],
 "Die Augen brauchen Zeit, um sich von hell auf dunkel umzustellen. Radfahrer oder Fußgänger im Schatten sehen Sie dann erst spät."),
]
